   892  static int
   893  lambda_body(codegen_scope *s, node *tree, int blk)
   894  {
   895    codegen_scope *parent = s;
   896    s = scope_new(s->mrb, s, tree->car);
   897
   898    s->mscope = !blk;
   899
   900    if (blk) {
   901      struct loopinfo *lp = loop_push(s, LOOP_BLOCK);
   902      lp->pc0 = new_label(s);
   903    }
   904    tree = tree->cdr;
   905    if (tree->car == NULL) {
   906      genop_W(s, OP_ENTER, 0);
   907      s->ainfo = 0;
   908    }
   909    else {
   910      mrb_aspec a;
   911      int ma, oa, ra, pa, ka, kd, ba;
   912      int pos, i;
   913      node *opt;
   914      node *margs, *pargs;
   915      node *tail;
   916
   917      /* mandatory arguments */
   918      ma = node_len(tree->car->car);
   919      margs = tree->car->car;
   920      tail = tree->car->cdr->cdr->cdr->cdr;
   921
   922      /* optional arguments */
   923      oa = node_len(tree->car->cdr->car);
   924      /* rest argument? */
   925      ra = tree->car->cdr->cdr->car ? 1 : 0;
   926      /* mandatory arguments after rest argument */
   927      pa = node_len(tree->car->cdr->cdr->cdr->car);
   928      pargs = tree->car->cdr->cdr->cdr->car;
   929      /* keyword arguments */
   930      ka = tail? node_len(tail->cdr->car) : 0;
   931      /* keyword dictionary? */
   932      kd = tail && tail->cdr->cdr->car? 1 : 0;
   933      /* block argument? */
   934      ba = tail && tail->cdr->cdr->cdr->car ? 1 : 0;
   935
   936      if (ma > 0x1f || oa > 0x1f || pa > 0x1f || ka > 0x1f) {
   937        codegen_error(s, "too many formal arguments");
   938      }
   939      a = MRB_ARGS_REQ(ma)
   940        | MRB_ARGS_OPT(oa)
   941        | (ra? MRB_ARGS_REST() : 0)
   942        | MRB_ARGS_POST(pa)
   943        | MRB_ARGS_KEY(ka, kd)
   944        | (ba? MRB_ARGS_BLOCK() : 0);
   945      s->ainfo = (((ma+oa) & 0x3f) << 7) /* (12bits = 5:1:5:1) */
   946        | ((ra & 0x1) << 6)
   947        | ((pa & 0x1f) << 1)
   948        | ((ka | kd) != 0 ? 0x01 : 0x00);
   949      genop_W(s, OP_ENTER, a);
   950      /* generate jump table for optional arguments initializer */
   951      pos = new_label(s);
   952      for (i=0; i<oa; i++) {
   953        new_label(s);
   954        genjmp_0(s, OP_JMP);
   955      }
   956      if (oa > 0) {
   957        genjmp_0(s, OP_JMP);
   958      }
   959      opt = tree->car->cdr->car;
   960      i = 0;
   961      while (opt) {
   962        int idx;
   963        mrb_sym id = nsym(opt->car->car);
   964
   965        dispatch(s, pos+i*3+1);
   966        codegen(s, opt->car->cdr, VAL);
   967        pop();
   968        idx = lv_idx(s, id);
   969        if (idx > 0) {
   970          gen_move(s, idx, cursp(), 0);
   971        }
   972        else {
   973          int lv = search_upvar(s, id, &idx);
   974          genop_3(s, OP_GETUPVAR, cursp(), idx, lv);
   975        }
   976        i++;
   977        opt = opt->cdr;
   978      }
   979      if (oa > 0) {
   980        dispatch(s, pos+i*3+1);
   981      }
   982
   983      /* keyword arguments */
   984      if (tail) {
   985        node *kwds = tail->cdr->car;
   986        int kwrest = 0;
   987
   988        if (tail->cdr->cdr->car) {
   989          kwrest = 1;
   990        }
   991        mrb_assert(nint(tail->car) == NODE_ARGS_TAIL);
   992        mrb_assert(node_len(tail) == 4);
   993
   994        while (kwds) {
   995          int jmpif_key_p, jmp_def_set = -1;
   996          node *kwd = kwds->car, *def_arg = kwd->cdr->cdr->car;
   997          mrb_sym kwd_sym = nsym(kwd->cdr->car);
   998
   999          mrb_assert(nint(kwd->car) == NODE_KW_ARG);
  1000
  1001          if (def_arg) {
  1002            int idx;
  1003            genop_2(s, OP_KEY_P, lv_idx(s, kwd_sym), new_sym(s, kwd_sym));
  1004            jmpif_key_p = genjmp2_0(s, OP_JMPIF, lv_idx(s, kwd_sym), NOVAL);
  1005            codegen(s, def_arg, VAL);
  1006            pop();
  1007            idx = lv_idx(s, kwd_sym);
  1008            if (idx > 0) {
  1009              gen_move(s, idx, cursp(), 0);
  1010            }
  1011            else {
  1012              int lv = search_upvar(s, kwd_sym, &idx);
  1013              genop_3(s, OP_GETUPVAR, cursp(), idx, lv);
  1014            }
  1015            jmp_def_set = genjmp_0(s, OP_JMP);
  1016            dispatch(s, jmpif_key_p);
  1017          }
  1018          genop_2(s, OP_KARG, lv_idx(s, kwd_sym), new_sym(s, kwd_sym));
  1019          if (jmp_def_set != -1) {
  1020            dispatch(s, jmp_def_set);
  1021          }
  1022          i++;
  1023
  1024          kwds = kwds->cdr;
  1025        }
  1026        if (tail->cdr->car && !kwrest) {
  1027          genop_0(s, OP_KEYEND);
  1028        }
  1029      }
  1030
  1031      /* argument destructuring */
  1032      if (margs) {
  1033        node *n = margs;
  1034
  1035        pos = 1;
  1036        while (n) {
  1037          if (nint(n->car->car) == NODE_MASGN) {
  1038            gen_vmassignment(s, n->car->cdr->car, pos, NOVAL);
  1039          }
  1040          pos++;
  1041          n = n->cdr;
  1042        }
  1043      }
  1044      if (pargs) {
  1045        node *n = margs;
  1046
  1047        pos = ma+oa+ra+1;
  1048        while (n) {
  1049          if (nint(n->car->car) == NODE_MASGN) {
  1050            gen_vmassignment(s, n->car->cdr->car, pos, NOVAL);
  1051          }
  1052          pos++;
  1053          n = n->cdr;
  1054        }
  1055      }
  1056    }
  1057
  1058    codegen(s, tree->cdr->car, VAL);
  1059    pop();
  1060    if (s->pc > 0) {
  1061      gen_return(s, OP_RETURN, cursp());
  1062    }
  1063    if (blk) {
  1064      loop_pop(s, NOVAL);
  1065    }
  1066    scope_finish(s);
  1067    return parent->irep->rlen - 1;
  1068  }
