  1070  static int
  1071  scope_body(codegen_scope *s, node *tree, int val)
  1072  {
  1073    codegen_scope *scope = scope_new(s->mrb, s, tree->car);
  1074
  1075    codegen(scope, tree->cdr, VAL);
  1076    gen_return(scope, OP_RETURN, scope->sp-1);
  1077    if (!s->iseq) {
  1078      genop_0(scope, OP_STOP);
  1079    }
  1080    scope_finish(scope);
  1081    if (!s->irep) {
  1082      /* should not happen */
  1083      return 0;
  1084    }
  1085    return s->irep->rlen - 1;
  1086  }
