  1088  static mrb_bool
  1089  nosplat(node *t)
  1090  {
  1091    while (t) {
  1092      if (nint(t->car->car) == NODE_SPLAT) return FALSE;
  1093      t = t->cdr;
  1094    }
  1095    return TRUE;
  1096  }
