  1098  static mrb_sym
  1099  attrsym(codegen_scope *s, mrb_sym a)
  1100  {
  1101    const char *name;
  1102    mrb_int len;
  1103    char *name2;
  1104
  1105    name = mrb_sym_name_len(s->mrb, a, &len);
  1106    name2 = (char *)codegen_palloc(s,
  1107                                   (size_t)len
  1108                                   + 1 /* '=' */
  1109                                   + 1 /* '\0' */
  1110                                   );
  1111    mrb_assert_int_fit(mrb_int, len, size_t, SIZE_MAX);
  1112    memcpy(name2, name, (size_t)len);
  1113    name2[len] = '=';
  1114    name2[len+1] = '\0';
  1115
  1116    return mrb_intern(s->mrb, name2, len+1);
  1117  }
